  </style>
</head>
<body>
  <h1>Workboard</h1>
  <label for="project-name">Project name</label>
  <input type="text" id="project-name" />
  <button id="create-btn">Create project</button>
  <div id="alert" class="alert" style="display:none;"></div>
  <h2>Projects</h2>
  <div id="project-list"></div>
  <script>
    async function fetchProjects() {
      const res = await fetch('/api/projects');
      const projects = await res.json();
      const list = document.getElementById('project-list');
      list.innerHTML = '';
      projects.forEach(p => {
        const div = document.createElement('div');
        div.className = 'project-row';
        div.setAttribute('data-testid', 'project-row');
        div.textContent = p.name + ' ';
        const btn = document.createElement('button');
        btn.textContent = 'Open project';
        btn.onclick = () => { location.href = `/projects/${p.id}`; };
        div.appendChild(btn);
        list.appendChild(div);
      });
    }

    document.getElementById('create-btn').addEventListener('click', async () => {
      const nameInput = document.getElementById('project-name');
      const name = nameInput.value.trim();
      const alertDiv = document.getElementById('alert');
      if (!name) {
        alertDiv.textContent = 'Project name is required';
        alertDiv.style.display = 'block';
        return;
      }
      alertDiv.style.display = 'none';
      const res = await fetch('/api/projects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name })
      });
      if (res.ok) {
        nameInput.value = '';
        await fetchProjects();
      } else {
        const err = await res.json();
        alertDiv.textContent = err.error || 'Error';
        alertDiv.style.display = 'block';
      }
    });

    fetchProjects();
  </script>
</body>
</html>
EOF

